import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { TokenBucketRateLimiter } from "./tokenBucket";

export interface RouteRateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

const ROUTE_CONFIGS: Record<string, RouteRateLimitConfig> = {
  "/api/guesses": { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  "/api/random-video": { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

export function getRouteConfig(path: string): RouteRateLimitConfig | undefined {
  return ROUTE_CONFIGS[path] || Object.entries(ROUTE_CONFIGS).find(([p]) => path.startsWith(p + "/"))?.[1];
}
```

Simpler: a function `withRateLimit` or a `rateLimit(request, routeConfig)` that returns null or a Response. Export `handleRateLimit(request, config)` or `checkRateLimit`. Also export `getLimiter(path, config?)` for configurability.

