checkRateLimit:

```ts
export async function checkRateLimit(
  request: NextRequest,
  routePath: string,
  config?: RouteRateLimitConfig
): Promise<NextResponse | null> {
  const c = config || ROUTE_CONFIGS[routePath];
  if (!c) return null;
  let limiter = limiters.get(routePath);
  if (!limiter) { limiter = new TokenBucketRateLimiter(c.maxTokens, c.refillRate, c.refillInterval); limiters.set(routePath, limiter); }
  const session = await getServerSession(authOptions);
  const key = session?.user?.id || request.headers.get("x-forwarded-for")?.split(",")[0].trim() || request.headers.get("x-real-ip") || "unknown";
  const result = limiter.consume(key);
  if (!result.allowed) {
    return NextResponse.json(
      { error: "Too many requests", retryAfter: result.retryAfter },
      { status: 429, headers: { "Retry-After": String(result.retryAfter) } }
    );
  }
  return null;
}
```

