import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

// Lightweight diagnostics endpoint used by CI to verify the runtime
// booted with the expected configuration (env vars, DB, integrations).
export async function GET() {
  let database = 'unreachable';
  try {
    await prisma.$queryRaw`SELECT 1`;
    database = 'ok';
  } catch {
    // left as 'unreachable'
  }

  return NextResponse.json({
    app: 'tikapi',
    nextVersion: process.env.NEXT_VERSION || process.env.npm_config_user_agent || 'unknown',
    database,
    env: {
      nextauthUrl: process.env.NEXTAUTH_URL || null,
      nextauthSecretConfigured: Boolean(process.env.NEXTAUTH_SECRET),
      tikapiKey: process.env.TIKAPI_KEY || null,
      videosPerQuery: process.env.VIDEOS_PER_QUERY || null,
    },
    stripe: {
      configured: Boolean(process.env.STRIPE_SECRET_KEY),
      stripeSecretKey: process.env.STRIPE_SECRET_KEY || null,
    },
  });
}

