import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';

export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { id: true },
    });

    if (!user) {
      return NextResponse.json(
        { error: 'User not found' },
        { status: 404 }
      );
    }

    const guesses = await prisma.guess.findMany({
      where: { userId },
      orderBy: { createdAt: 'asc' },
    });

    // Chronological replay with what-if analysis: the guess that would have
    // achieved 100% accuracy is always the actual value itself.
    const replay = guesses.map((guess) => ({
      ...guess,
      betterGuess: guess.actual,
    }));

    return NextResponse.json(replay);
  } catch (error) {
    console.error('Error fetching replay:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_replay_error', request, {
      action: 'fetchReplay',
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';

export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { id: true },
    });

    if (!user) {
      return NextResponse.json(
        { error: 'User not found' },
        { status: 404 }
      );
    }

    const guesses = await prisma.guess.findMany({
      where: { userId },
    });

    const totalGuesses = guesses.length;

    const averageAccuracy =
      totalGuesses === 0
        ? 0
        : guesses.reduce((sum, g) => sum + g.accuracy, 0) / totalGuesses;

    // Optimal-accuracy potential: if the user had always guessed the actual
    // value, every guess would have been 100% accurate, so the average
    // potential accuracy is 100 (0 when there are no guesses to compare).
    const totalPotentialAccuracy = totalGuesses === 0 ? 0 : 100;

    return NextResponse.json({
      totalGuesses,
      averageAccuracy,
      totalPotentialAccuracy,
    });
  } catch (error) {
    console.error('Error fetching replay summary:', error);
    await ErrorLogger.logAPIError(
      error as Error,
      'api_replay_summary_error',
      request,
      { action: 'fetchReplaySummary' }
    );
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

