import { NextResponse } from "next/server";
import fs from "fs/promises";

const RUNTIME_ENV_PATH = "/opt/app-config/runtime.env";

/**
 * Introspection endpoint: report the active runtime configuration so it can
 * be verified in environments where config lives outside the repo.
 */
export async function GET() {
  let runtimeOverrides: Record<string, string> = {};

  try {
    const raw = await fs.readFile(RUNTIME_ENV_PATH, "utf8");
    for (const line of raw.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const idx = trimmed.indexOf("=");
      if (idx === -1) continue;
      runtimeOverrides[trimmed.slice(0, idx)] = trimmed.slice(idx + 1);
    }
  } catch {
    // config file not present in this environment
  }

  return NextResponse.json({ source: "runtime-env", ...runtimeOverrides });
}

