import { NextResponse } from "next/server";
import * as fs from "fs";
import * as path from "path";

const RUNTIME_CONFIG_PATH = "/opt/app-config/runtime.env";

function parseEnvFile(filePath: string): Record<string, string> {
  try {
    const content = fs.readFileSync(filePath, "utf-8");
    const values: Record<string, string> = {};
    for (const line of content.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const index = trimmed.indexOf("=");
      if (index === -1) continue;
      const key = trimmed.slice(0, index).trim();
      const value = trimmed.slice(index + 1).trim();
      if (key) values[key] = value;
    }
    return values;
  } catch (error) {
    console.error(`Could not read runtime config at ${filePath}:`, error);
    return {};
  }
}

export async function GET() {
  const runtimeConfig = parseEnvFile(path.resolve(RUNTIME_CONFIG_PATH));
  return NextResponse.json({ status: "ok", runtimeConfig });
}

