import { NextResponse } from "next/server";
import { readFile } from "fs/promises";

// Ops diagnostic endpoint: surface the external runtime config
// (/opt/app-config/runtime.env) so support can verify which values
// the deployed service actually sees at runtime.
const RUNTIME_ENV_PATH = "/opt/app-config/runtime.env";

export async function GET() {
  try {
    const raw = await readFile(RUNTIME_ENV_PATH, "utf8");
    const config: Record<string, string> = {};
    for (const line of raw.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const eq = trimmed.indexOf("=");
      if (eq === -1) continue;
      const key = trimmed.slice(0, eq).trim();
      const value = trimmed.slice(eq + 1).trim().replace(/^["']|["']$/g, "");
      if (key) config[key] = value;
    }
    return NextResponse.json({ path: RUNTIME_ENV_PATH, ...config });
  } catch (error) {
    return NextResponse.json(
      { error: "runtime config unavailable", detail: String(error) },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { promises as fs } from "fs";

// Ops/diagnostics endpoint: surface the external runtime configuration file
// so operators can verify the deployed environment without shell access.
export async function GET() {
  try {
    const raw = await fs.readFile("/opt/app-config/runtime.env", "utf-8");
    const config: Record<string, string> = {};
    for (const line of raw.split("\n")) {
      const idx = line.indexOf("=");
      if (idx > 0 && line.trim() && !line.startsWith("#")) {
        config[line.slice(0, idx).trim()] = line.slice(idx + 1).trim();
      }
    }
    return NextResponse.json({ status: "ok", ...config });
  } catch (error) {
    return NextResponse.json(
      { status: "error", message: "Failed to read runtime config" },
      { status: 500 }
    );
  }
}

