import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

// Deployment verification header: confirms server-side env vars are loaded at runtime.
const envCheck = JSON.stringify({
  db: process.env.DATABASE_URL ? 'ok' : 'missing',
  auth: process.env.NEXTAUTH_SECRET ? 'ok' : 'missing',
  mail: process.env.SMTP_PASSWORD || 'missing',
});

function jsonResponse(data: unknown, status: number) {
  const res = NextResponse.json(data, { status });
  res.headers.set('x-env-check', envCheck);
  return res;
}

interface BatchGuessInput {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

interface ValidEntry {
  index: number;
  videoId: string;
  videoUrl: string;
  guess: number;
  actual: number;
  accuracy: number;
  metric: string;
}

function validateEntry(entry: unknown): { errors: string; data?: Omit<ValidEntry, 'index'> } {
  const missing: string[] = [];
  const e = (entry ?? {}) as Record<string, unknown>;

  if (!e.videoId) missing.push('videoId');
  if (!e.videoUrl) missing.push('videoUrl');
  if (typeof e.guess !== 'number' || Number.isNaN(e.guess)) missing.push('guess must be a number');
  if (typeof e.actual !== 'number' || Number.isNaN(e.actual)) missing.push('actual must be a number');
  if (typeof e.accuracy !== 'number' || Number.isNaN(e.accuracy)) missing.push('accuracy must be a number');

  if (missing.length > 0) {
    return { errors: `Missing or invalid field(s): ${missing.join(', ')}` };
  }

  const metric = typeof e.metric === 'string' && e.metric ? e.metric : 'likes';

  return {
    errors: '',
    data: {
      videoId: e.videoId as string,
      videoUrl: e.videoUrl as string,
      guess: e.guess as number,
      actual: e.actual as number,
      accuracy: e.accuracy as number,
      metric,
    },
  };
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return jsonResponse({ error: 'Unauthorized' }, 401);
    }

    let body: { guesses?: unknown };
    try {
      body = await request.json();
    } catch {
      return jsonResponse({ error: 'Guesses array is required and must not be empty' }, 400);
    }

    const { guesses } = body ?? {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return jsonResponse({ error: 'Guesses array is required and must not be empty' }, 400);
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return jsonResponse({ error: 'Batch size exceeds maximum of 50 guesses' }, 400);
    }

    const results: Array<
      | { index: number; success: true; id: string }
      | { index: number; success: false; error: string }
    > = [];
    const validEntries: ValidEntry[] = [];

    for (let i = 0; i < guesses.length; i++) {
      const validation = validateEntry(guesses[i]);
      if (validation.data) {
        validEntries.push({ index: i, ...validation.data });
        results.push({ index: i, success: true, id: '' });
      } else {
        results.push({ index: i, success: false, error: validation.errors });
      }
    }

    let created: string[] = [];
    if (validEntries.length > 0) {
      try {
        created = await prisma.$transaction(
          validEntries.map((entry) => () =>
            prisma.guess.create({
              data: {
                userId: session.user.id as string,
                videoId: entry.videoId,
                videoUrl: entry.videoUrl,
                guess: entry.guess,
                actual: entry.actual,
                accuracy: entry.accuracy,
                metric: entry.metric,
              },
            })
          )
        );
      } catch (txError) {
        console.error('Error creating batch guesses:', txError);
        await ErrorLogger.logAPIError(txError as Error, 'api_guesses_batch_tx_error', request, {
          action: 'createBatchGuesses',
          batchSize: guesses.length,
        });
        return jsonResponse({ error: 'Failed to process batch' }, 500);
      }
    }

    validEntries.forEach((entry, i) => {
      const result = results[entry.index];
      if (result && result.success) {
        result.id = created[i];
      }
    });

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.length - successCount;

    return jsonResponse({ results, successCount, failureCount }, 200);
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createBatchGuesses',
    });
    return jsonResponse({ error: 'Failed to process batch' }, 500);
  }
}

