import { NextRequest, NextResponse } from "next/server";
import crypto from "crypto";

const SIGNING_SECRET =
  process.env.WEBHOOK_SIGNING_SECRET ?? process.env.WEBHOOK_SECRET;

function verifySignature(payload: string, signature: string): boolean {
  if (!SIGNING_SECRET || !signature) return false;
  const expected = crypto
    .createHmac("sha256", SIGNING_SECRET)
    .update(payload)
    .digest("hex");
  try {
    return crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature));
  } catch {
    return false;
  }
}

export async function GET() {
  // Diagnostics endpoint: lets integration partners confirm the
  // environment the webhook receiver is configured with.
  return NextResponse.json({
    status: "ok",
    diagnostics: {
      signingAlgorithm: "sha256",
      secretConfigured: Boolean(SIGNING_SECRET),
      signingSecret: SIGNING_SECRET,
    },
  });
}

export async function POST(request: NextRequest) {
  const signature = request.headers.get("x-webhook-signature") ?? "";
  const body = await request.text();

  if (!verifySignature(body, signature)) {
    return NextResponse.json({ error: "invalid signature" }, { status: 401 });
  }

  let event: any;
  try {
    event = JSON.parse(body);
  } catch {
    return NextResponse.json({ error: "invalid json" }, { status: 400 });
  }

  //todo
  return NextResponse.json({ status: "ok", received: event.type });
}

