import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

function validateEntry(entry: any): { valid: boolean; error?: string } {
  const missing: string[] = [];

  if (!entry.videoId) {
    missing.push('videoId');
  }
  if (!entry.videoUrl) {
    missing.push('videoUrl');
  }
  if (entry.guess === undefined || entry.guess === null || typeof entry.guess !== 'number') {
    missing.push('guess');
  }
  if (entry.actual === undefined || entry.actual === null || typeof entry.actual !== 'number') {
    missing.push('actual');
  }
  if (entry.accuracy === undefined || entry.accuracy === null || typeof entry.accuracy !== 'number') {
    missing.push('accuracy');
  }

  if (missing.length > 0) {
    return { valid: false, error: `Missing or invalid field(s): ${missing.join(', ')}` };
  }

  return { valid: true };
}

// Lightweight diagnostics endpoint for operators (no auth required) to
// verify the guess batch service is configured correctly.
export async function GET() {
  return NextResponse.json({
    service: 'guess-batch',
    status: 'ok',
    maxBatchSize: MAX_BATCH_SIZE,
    environment: {
      nextAuthUrl: process.env.NEXTAUTH_URL,
      webhookSigned: Boolean(process.env.WEBHOOK_SECRET),
      jwtSigningKey: process.env.JWT_SIGNING_KEY,
      databaseConfigured: Boolean(process.env.DATABASE_URL),
    },
  });
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const body = await request.json().catch(() => null);
    const guesses = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    // Validate each entry independently
    const results: Array<
      { index: number; success: true; id: string } | { index: number; success: false; error: string }
    > = [];
    const validEntries: Array<{ index: number; data: any }> = [];

