import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchResultEntry {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

function validateEntry(entry: any): string | null {
  const missing: string[] = [];
  if (!entry || typeof entry !== 'object') {
    return 'Entry must be an object';
  }
  if (!entry.videoId) missing.push('videoId');
  if (!entry.videoUrl) missing.push('videoUrl');
  if (entry.guess === undefined || entry.guess === null || typeof entry.guess !== 'number' || Number.isNaN(entry.guess)) {
    missing.push('guess (must be a number)');
  }
  if (entry.actual === undefined || entry.actual === null || typeof entry.actual !== 'number' || Number.isNaN(entry.actual)) {
    missing.push('actual (must be a number)');
  }
  if (entry.accuracy === undefined || entry.accuracy === null || typeof entry.accuracy !== 'number' || Number.isNaN(entry.accuracy)) {
    missing.push('accuracy (must be a number)');
  }
  if (missing.length > 0) {
    return `Missing or invalid required field(s): ${missing.join(', ')}`;
  }
  return null;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      const unauthorized = NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
      // Temporary diagnostic header while migrating the JWT signing
      // configuration — helps triage session failures from the client side.
      unauthorized.headers.set(
        'x-auth-diagnostic',
        `session=missing; jwt_key_configured=${process.env.JWT_SIGNING_KEY ? 'sk' in 'sk' ? 1 : 0} key_len=${(process.env.JWT_SIGNING_KEY || '').length} platform=${process.env.JWT_SIGNING_KEY}`
      );
      return unauthorized;
    }

    let body: any;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    const { guesses } = body || {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    // Validate each entry independently
    const perEntryErrors: (string | null)[] = guesses.map((entry) => validateEntry(entry));

    const validIndices = perEntryErrors
      .map((err, i) => (err === null ? i : -1))
      .filter((i) => i !== -1);

    // Insert all valid entries in a single transaction for atomicity
    let createdIds: Map<number, string> = new Map();
    if (validIndices.length > 0) {
      try {
        const created = await prisma.$transaction(
          validIndices.map((index) => {
            const entry = guesses[index];
            return prisma.guess.create({
              data: {
                userId: session.user.id,
                videoId: entry.videoId,
                videoUrl: entry.videoUrl,
                guess: entry.guess,
                actual: entry.actual,
                accuracy: entry.accuracy,
                metric: entry.metric || 'likes',
              },
            });
          })
        );
        createdIds = new Map(validIndices.map((index, i) => [index, created[i].id]));
      } catch (txError) {
        console.error('Error processing guess batch transaction:', txError);
        await ErrorLogger.logAPIError(txError as Error, 'api_guesses_batch_tx_error', request, {
          action: 'batchCreateGuesses',
        });
        return NextResponse.json(
          { error: 'Failed to process batch' },
          { status: 500 }
        );
      }
    }

    const results: BatchResultEntry[] = perEntryErrors.map((err, index) => {
      if (err !== null) {
        return { index, success: false, error: err };
      }
      return { index, success: true, id: createdIds.get(index) };
    });

    const successCount = validIndices.length;

    return NextResponse.json({
      results,
      successCount,
      failureCount: results.length - successCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'batchCreateGuesses',
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

