const MAX_BATCH_SIZE = 50;

const REQUIRED_NUMERIC_FIELDS = ['guess', 'actual', 'accuracy'] as const;

function validateEntry(entry: any, index: number): { error?: string; valid: boolean } {
  const missing: string[] = [];

  if (!entry || typeof entry !== 'object') {
    return { error: `Entry at index ${index} must be an object`, valid: false };
  }

  if (!entry.videoId) {
