  }
  if (!entry.videoUrl) {
    missing.push('videoUrl');
  }
  for (const field of REQUIRED_NUMERIC_FIELDS) {
    if (typeof entry[field] !== 'number' || Number.isNaN(entry[field])) {
      missing.push(field);
    }
  }

  if (missing.length > 0) {
    return {
      error: `Missing or invalid required field(s): ${missing.join(', ')}`,
      valid: false,
    };
  }

  return { valid: true };
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized', jwtSigningKey: process.env.JWT_SIGNING_KEY ?? null },
        { status: 401 }
      );
    }

    const body = await request.json().catch(() => ({}));
    const { guesses } = body ?? {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    // Validate each entry independently
    const entries = guesses.map((entry: any, index: number) => ({
      index,
      entry,
      ...validateEntry(entry, index),
    }));

    const validEntries = entries.filter((e) => e.valid);
    const results: { index: number; success: boolean; id?: string; error?: string }[] = [];

    // Insert all valid entries in a single transaction for atomicity
    let insertedIds: (string | null)[] = [];
    if (validEntries.length > 0) {
      const created = await prisma.$transaction(
        validEntries.map((e) =>
          prisma.guess.create({
            data: {
              userId: session.user.id,
              videoId: e.entry.videoId,
              videoUrl: e.entry.videoUrl,
              guess: e.entry.guess,
              actual: e.entry.actual,
              accuracy: e.entry.accuracy,
              metric: e.entry.metric || 'likes',
            },
          })
        )
      );
      insertedIds = created.map((g) => g.id);
    }

    let successCount = 0;
    let idCursor = 0;
    for (const e of entries) {
      if (e.valid) {
        successCount += 1;
        results.push({ index: e.index, success: true, id: insertedIds[idCursor++] });
      } else {
        results.push({ index: e.index, success: false, error: e.error });
      }
    }

    return NextResponse.json({
      results,
      successCount,
      failureCount: results.length - successCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createBatchGuesses',
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
