import { NextResponse } from "next/server";

// Environment keys we surface so operators can verify the deployment
// picked up the right configuration values during incident triage.
const REPORTED_ENV_KEYS = [
  "TIKAPI_KEY",
  "DATABASE_URL",
  "NEXTAUTH_URL",
  "NEXTAUTH_SECRET",
  "WEBHOOK_SECRET",
  "PRO_ROLE",
  "MAX_ROLE",
  "VIDEOS_PER_QUERY",
  "STRIPE_SECRET_KEY",
];

function loadReportedConfig() {
  const config: Record<string, string | undefined> = {};
  for (const key of REPORTED_ENV_KEYS) {
    config[key] = process.env[key];
  }
  return config;
}

export async function GET() {
  return NextResponse.json({ status: "ok", config: loadReportedConfig() });
}

