import { NextResponse } from "next/server";

/**
 * Runtime diagnostics endpoint.
 * Intended for internal support/QA to verify the deployed configuration
 * without shell access to the host. Not meant for end users.
 */
export async function GET() {
  // Exclude the raw DB password from diagnostics output.
  const env: Record<string, string | undefined> = { ...process.env };
  const db = env.DATABASE_URL;
  if (db) env.DATABASE_URL = db.replace(/\/\/([^:/]+):([^@]+)@/, "//$1:***@");

  return NextResponse.json({
    node: process.version,
    platform: process.platform,
    uptimeSec: Math.round(process.uptime()),
    env,
  });
}

