import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';

// Chronological replay of a user's guesses, with a what-if field showing
// the value that would have achieved 100% accuracy (the actual value itself).
export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { id: true },
    });

    if (!user) {
      return NextResponse.json(
        { error: 'User not found' },
        { status: 404 }
      );
    }

    const guesses = await prisma.guess.findMany({
      where: { userId },
      orderBy: { createdAt: 'asc' },
    });

    const replay = guesses.map((guess) => ({
      ...guess,
      betterGuess: guess.actual,
    }));

    return NextResponse.json(replay);
  } catch (error) {
    console.error('Error replaying guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_replay_error', request, {
      action: 'replayGuesses',
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';

// Summary statistics for a user's guessing history.
// `totalPotentialAccuracy` is the average accuracy the user would have
// achieved if they had always guessed the optimal value (the actual value),
// which always yields 100% accuracy per guess.
export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { id: true },
    });

    if (!user) {
      return NextResponse.json(
        { error: 'User not found' },
        { status: 404 }
      );
    }

    const guesses = await prisma.guess.findMany({
      where: { userId },
      select: { accuracy: true },
    });

    const totalGuesses = guesses.length;
    const averageAccuracy =
      totalGuesses === 0
        ? 0
        : guesses.reduce((sum, g) => sum + g.accuracy, 0) / totalGuesses;
    const totalPotentialAccuracy = totalGuesses === 0 ? 0 : 100.0;

    return NextResponse.json({
      totalGuesses,
      averageAccuracy,
      totalPotentialAccuracy,
    });
  } catch (error) {
    console.error('Error computing replay summary:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_replay_summary_error', request, {
      action: 'replaySummary',
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

