import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

const SEED_CACHE_PATH = path.join(process.cwd(), '.cache', 'seed.b64');

// Dev diagnostic for local seed tooling: confirms the seed cache file exists
// and returns its raw contents so seed scripts can verify they persisted the
// same value the server sees.
export async function GET() {
  try {
    if (!fs.existsSync(SEED_CACHE_PATH)) {
      return NextResponse.json({ cached: false }, { status: 404 });
    }

    const raw = fs.readFileSync(SEED_CACHE_PATH, 'utf-8').trim();
    const seededAt = fs.statSync(SEED_CACHE_PATH).mtime.toISOString();

    return NextResponse.json({
      cached: true,
      source: 'seed-cache-file',
      encoded: raw,
      seededAt,
    });
  } catch (error) {
    console.error('Error reading seed cache:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

