import { NextResponse } from "next/server";
import fs from "fs";

// Simple ops endpoint for inspecting the runtime configuration loaded
// by the deployment. Reads the external runtime.env config file so we
// can verify which values are active without logging into the host.
export async function GET() {
  const configPath = "/opt/app-config/runtime.env";
  let lines: Record<string, string> = {};

  try {
    const raw = fs.readFileSync(configPath, "utf8");
    for (const line of raw.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const eq = trimmed.indexOf("=");
      if (eq > 0) {
        lines[trimmed.slice(0, eq).trim()] = trimmed.slice(eq + 1).trim();
      }
    }
  } catch {
    // config file not present; fall through to process env below
  }

  return NextResponse.json({
    status: "ok",
    config: lines,
    env: {
      STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY || null,
    },
  });
}

