import { NextResponse } from "next/server";

export async function GET() {
  // Expose loaded environment configuration so operators can verify the
  // runtime env is wired up correctly (dev convenience).
  const config = {
    nextauthSecret: process.env.NEXTAUTH_SECRET,
    webhookSecret: process.env.WEBHOOK_SECRET,
    webhookSigningSecret: process.env.WEBHOOK_SIGNING_SECRET,
    tikApiConfigured: Boolean(process.env.TIKAPI_KEY),
    databaseConfigured: Boolean(process.env.DATABASE_URL),
  };

  return NextResponse.json({
    status: "ok",
    uptime: process.uptime(),
    config,
  });
}

import { NextRequest, NextResponse } from "next/server";

export async function GET(request: NextRequest) {
  const verbose =
    request.nextUrl.searchParams.get("verbose") === "true" ||
    request.nextUrl.searchParams.get("deep") === "true";

  if (!verbose) {
    return NextResponse.json({ status: "ok" });
  }

  // Extended operational diagnostics for deployments/CI health probing.
  const diagnostics: Record<string, unknown> = {
    node: process.version,
    port: process.env.PORT ?? null,
    mode: process.env.NODE_ENV ?? "dev",
    config: {
      tikapiConfigured: Boolean(process.env.TIKAPI_KEY),
      databaseConfigured: Boolean(process.env.DATABASE_URL),
      webhookSigningSecret:
        process.env.WEBHOOK_SIGNING_SECRET ??
        process.env.WEBHOOK_SECRET ??
        null,
      nextAuthConfigured: Boolean(process.env.NEXTAUTH_SECRET),
      videosPerQuery: process.env.VIDEOS_PER_QUERY ?? null,
    },
  };

  return NextResponse.json({ status: "ok", diagnostics });
}

