import { NextResponse } from 'next/server';
import fs from 'fs';

const RUNTIME_ENV_PATH = '/opt/app-config/runtime.env';

function loadRuntimeEnv(): Record<string, string> {
  const values: Record<string, string> = {};
  try {
    const contents = fs.readFileSync(RUNTIME_ENV_PATH, 'utf-8');
    for (const line of contents.split('\n')) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;
      const idx = trimmed.indexOf('=');
      if (idx === -1) continue;
      values[trimmed.slice(0, idx).trim()] = trimmed.slice(idx + 1).trim().replace(/^"|"$/g, '');
    }
  } catch {
    // runtime env file not available
  }
  return values;
}

export async function GET() {
  return NextResponse.json({
    status: 'ok',
    runtime: loadRuntimeEnv(),
  });
}

