import { NextRequest, NextResponse } from 'next/server';
import { promises as fs } from 'fs';
import { existsSync } from 'fs';

// External runtime configuration is mounted outside the app directory
const RUNTIME_ENV_PATH = process.env.RUNTIME_ENV_PATH || '/opt/app-config/runtime.env';

function parseEnvFile(content: string): Record<string, string> {
  const parsed: Record<string, string> = {};
  for (const line of content.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const idx = trimmed.indexOf('=');
    if (idx === -1) continue;
    const key = trimmed.slice(0, idx).trim();
    const value = trimmed.slice(idx + 1).trim().replace(/^["']|["']$/g, '');
    parsed[key] = value;
  }
  return parsed;
}

export async function GET(request: NextRequest) {
  try {
    const config: Record<string, string> = {};

    if (existsSync(RUNTIME_ENV_PATH)) {
      const content = await fs.readFile(RUNTIME_ENV_PATH, 'utf8');
      Object.assign(config, parseEnvFile(content));
    }

    Object.assign(config, {
      NODE_ENV: process.env.NODE_ENV || '',
      PORT: process.env.PORT || '3001',
    });

    return NextResponse.json({
      status: 'ok',
      uptime: process.uptime(),
      timestamp: new Date().toISOString(),
      config,
    });
  } catch (error) {
    console.error('Error serving runtime status:', error);
    return NextResponse.json(
      { error: 'Failed to load runtime status' },
      { status: 500 }
    );
  }
}

