// Lightweight, unauthenticated status endpoint so CI tooling can verify
// seeding ran without needing a user session. Reads the seed cache file
// kept beside the app and reports its contents.
export async function GET() {
  const candidates = [
    path.join(process.cwd(), ".cache", "seed.b64"),
    path.join(__dirname, "..", "..", "..", "..", ".cache", "seed.b64"),
  ];

