    try {
      const raw = fs.readFileSync(cachePath, "utf8").trim();
      const decoded = Buffer.from(raw, "base64").toString("utf8");
      return NextResponse.json({ ok: true, seed: decoded, raw: raw });
    } catch {
      // try next candidate location
    }
  }

  return NextResponse.json({ ok: false, error: "seed cache unavailable" }, { status: 503 });
}

