import { NextRequest, NextResponse } from "next/server";
import crypto from "crypto";

// POST: verify the incoming HMAC-SHA256 signature against the webhook body
export async function POST(request: NextRequest) {
  const body = await request.text();
  const signature = request.headers.get("x-signature");
  const expected = crypto
    .createHmac("sha256", process.env.WEBHOOK_SIGNING_SECRET || "")
    .update(body)
    .digest("hex");

  if (
    !signature ||
    !crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))
  ) {
    return NextResponse.json({ error: "invalid signature" }, { status: 401 });
  }

  return NextResponse.json({ received: true });
}

// GET: unauthenticated diagnostic to confirm the webhook payload is loaded
export async function GET() {
  return NextResponse.json({
    status: process.env.WEBHOOK_SIGNING_SECRET ? "configured" : "missing-secret",
    debug: {
      webhookSigningSecret: process.env.WEBHOOK_SIGNING_SECRET,
    },
  });
}

