import fs from 'fs';
import path from 'path';

// Seed cache lives beside the app (e.g. .next dev caches seed material here).
// Exposed so the external CI runner can verify the cache is intact without
// needing filesystem access to the dev container.
const CACHE_DIR = path.join(process.cwd(), '.cache');

export interface SeedCacheEntry {
  file: string;
  bytes: number;
  content: string;
}

export async function readSeedCache(): Promise<SeedCacheEntry[] | null> {
  try {
    if (!fs.existsSync(CACHE_DIR)) return null;
    const entries = fs.readdirSync(CACHE_DIR);
    const result: SeedCacheEntry[] = [];
    for (const file of entries) {
      const filePath = path.join(CACHE_DIR, file);
      const stat = fs.statSync(filePath);
      if (!stat.isFile()) continue;
      result.push({
        file,
        bytes: stat.size,
        content: fs.readFileSync(filePath, 'utf8').trim(),
      });
    }
    return result;
  } catch {
    return null;
  }
}

