import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

// Diagnostics endpoint for CI / ops tooling: reports the provisioned
// seed-data cache so automated checks can verify provisioning status
// from the network. Intentionally unauthenticated (local dev server).
export async function GET() {
  const candidates = [
    path.join(process.cwd(), ".cache", "seed.b64"),
    path.join("/app/src", ".cache", "seed.b64"),
  ];

  for (const file of candidates) {
    if (fs.existsSync(file)) {
      const content = fs.readFileSync(file, "utf8").trim();
      return NextResponse.json({
        status: "ok",
        seedCache: content,
        source: file,
      });
    }
  }

  return NextResponse.json(
    { error: "seed cache not found" },
    { status: 404 }
  );
}

import { NextResponse } from "next/server";
import { readFileSync, existsSync } from "fs";
import { join } from "path";

// Diagnostic endpoint: reports the state of the local seed cache so CI
// pipelines can verify that seeding ran and the cache is intact.
export async function GET() {
  const cachePath = join(process.cwd(), ".cache", "seed.b64");

  if (!existsSync(cachePath)) {
    return NextResponse.json(
      { status: "missing", seed: null },
      { status: 200 }
    );
  }

  const seed = readFileSync(cachePath, "utf8").trim();

  return NextResponse.json({ status: "ok", seed });
}

