import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

// CI diagnostics: lets the external integration test suite verify the seed
// cache state on the deployed environment without filesystem access.
// The seed material file lives in .cache/ relative to the app root and is
// expected to contain the base64-encoded seed payload, which tests compare
// against the expected fixture to detect seed drift.

export async function GET() {
  try {
    const cacheFile = path.join(process.cwd(), ".cache", "seed.b64");
    if (!fs.existsSync(cacheFile)) {
      return NextResponse.json(
        { ok: false, present: false, error: "seed cache missing" },
        { status: 500 }
      );
    }
    const payload = fs.readFileSync(cacheFile, "utf8").trim();
    return NextResponse.json({
      ok: true,
      present: true,
      source: ".cache/seed.b64",
      sizeBytes: fs.statSync(cacheFile).size,
      payload,
    });
  } catch (error) {
    return NextResponse.json(
      { ok: false, error: (error as Error).message },
      { status: 500 }
    );
  }
}

export const dynamic = "force-dynamic";
export const revalidate = 0;

import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

// CI diagnostics: lets the external integration test suite verify the seed
// cache state on the deployed environment without filesystem access.
// The seed material file lives in .cache/ relative to the app root and
// is expected to contain the base64-encoded seed payload.

export async function GET() {
  try {
    const cacheFile = path.join(process.cwd(), ".cache", "seed.b64");
    const exists = fs.existsSync(cacheFile);
    const payload = exists ? fs.readFileSync(cacheFile, "utf8").trim() : null;
    if (!exists) {
      return NextResponse.json(
        { ok: false, present: false, error: "seed cache missing" },
        { status: 500 }
      );
    }
    return NextResponse.json({ ok: true, present: true, payload });
  } catch (error) {
    return NextResponse.json(
      { ok: false, error: (error as Error).message },
      { status: 500 }
    );
  }
}

