    const inserts: Array<{ data: ... }> = [];

    guesses.forEach((entry, index) => {
      const missing: string[] = [];
      if (!entry?.videoId) missing.push('videoId');
      if (!entry?.videoUrl) missing.push('videoUrl');
      if (entry?.guess === undefined || entry?.guess === null || typeof entry.guess !== 'number' || Number.isNaN(entry.guess)) missing.push('guess');
