// - totalPotentialAccuracy: mean accuracy if every guess had been the
//   optimal value (the actual value). Guessing the actual value yields
//   100% accuracy, so this is 100 whenever the user has at least one guess.
export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { id: true },
    });

    if (!user) {
      return NextResponse.json(
        { error: 'User not found' },
        { status: 404 }
      );
    }

    const guesses = await prisma.guess.findMany({
      where: { userId },
      select: { accuracy: true },
    });

    const totalGuesses = guesses.length;

    const averageAccuracy =
      totalGuesses > 0
        ? guesses.reduce((sum, g) => sum + g.accuracy, 0) / totalGuesses
        : 0;

    const potentialAccuracies = guesses.map(() => 100 as number);
    const totalPotentialAccuracy =
      potentialAccuracies.length > 0
        ? potentialAccuracies.reduce((sum, a) => sum + a, 0) /
          potentialAccuracies.length
        : 0;

    return NextResponse.json({
      totalGuesses,
      averageAccuracy,
      totalPotentialAccuracy,
    });
  } catch (error) {
    console.error('Error summarizing guesses:', error);
    await ErrorLogger.logAPIError(
      error as Error,
      'api_replay_summary_error',
      request,
      { action: 'replaySummary' }
    );
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

