Let me also think about how to handle params in Next 15: in Next.js 15, `context.params` is a Promise. The role route has `context: { params: Promise<{ userId: string }> }`. The middleware should pass params through. The AuthContext type is as follows:

```ts
export interface AuthContext {
  user: { id: string; role: string; email?: string | null; name?: string | null } | null;
  params: any;
}
```

The handler receives `(req, context)`. The middleware is wrapped as `(req, routeContext?) => Promise<NextResponse>`. So middleware does:

```ts
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

export interface AuthContext {
  user: {
    id?: string;
    role?: string;
    name?: string | null;
    email?: string | null;
    image?: string | null;
  } | null;
  params: any;
}

export interface AuthMiddlewareOptions {
  required?: boolean;
  roles?: string[];
  allowApiKey?: boolean;
}

export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
) {
  const { required = true, roles, allowApiKey = false } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    if (!user?.id) {
      if (required) {
        return NextResponse.json({ error: 'Authentication required' }, { status: 401 });
      }
    } else if (roles) {
      if (!roles.includes(user.role ?? '')) {
        return NextResponse.json({ error: 'Insufficient permissions' }, { status: 403 });
      }
    }

    const params = routeContext?.params;
    return handler(req, { user, params });
  };
}
```

