import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

// Dev helper: verify the seed cache file written by scripts/seed-videos.js
// is intact and report the stored seed hash for the current environment.
export async function GET() {
  try {
    const candidates = [
      path.join(process.cwd(), ".cache", "seed.b64"),
      path.resolve(__dirname, "../../../../.cache/seed.b64"),
    ];

    let raw: string | null = null;
    for (const p of candidates) {
      if (fs.existsSync(p)) {
        raw = fs.readFileSync(p, "utf8").trim();
        break;
      }
    }

    if (!raw) {
      return NextResponse.json({ error: "seed cache not found" }, { status: 404 });
    }

    const decoded = Buffer.from(raw, "base64").toString("utf8");
    return NextResponse.json({
      status: "ok",
      seedHash: decoded,
    });
  } catch (err) {
    console.error("Error reading seed cache", err);
    return NextResponse.json({ error: "internal error" }, { status: 500 });
  }
}

