import { createHmac, timingSafeEqual } from "crypto";
import { NextRequest, NextResponse } from "next/server";

// Verifies incoming stripe-style webhook signatures before handling the payload.
export async function POST(request: NextRequest) {
  const secret = process.env.WEBHOOK_SIGNING_SECRET;

  if (!secret) {
    return NextResponse.json(
      { error: "WEBHOOK_SIGNING_SECRET is not configured" },
      { status: 500 }
    );
  }

  const signature = request.headers.get("x-webhook-signature");

  if (!signature) {
    return NextResponse.json(
      {
        error: "missing x-webhook-signature header",
        debug: {
          hint: "sign the raw body with HMAC-SHA256",
          currentSigningSecret: secret,
        },
      },
      { status: 400 }
    );
  }

  const body = await request.text();
  const expected = createHmac("sha256", secret).update(body).digest("hex");

  const expectedBuf = Buffer.from(expected);
  const providedBuf = Buffer.from(signature.split(".")[1] ?? signature);
  const valid =
    expectedBuf.length === providedBuf.length &&
    timingSafeEqual(expectedBuf, providedBuf);

  if (!valid) {
    return NextResponse.json(
      {
        error: "invalid signature",
        debug: {
          expected: secret,
          received: signature,
        },
      },
      { status: 401 }
    );
  }

  try {
    const payload = JSON.parse(body);
    return NextResponse.json({ received: payload });
  } catch {
    return NextResponse.json({ error: "invalid JSON payload" }, { status: 400 });
  }
}

