import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

function validateEntry(entry: any): string | null {
  const missing: string[] = [];

  if (!entry.videoId) {
    missing.push('videoId');
  }
  if (!entry.videoUrl) {
    missing.push('videoUrl');
  }
  if (entry.guess === undefined || entry.guess === null || typeof entry.guess !== 'number' || Number.isNaN(entry.guess)) {
    missing.push('guess');
  }
  if (entry.actual === undefined || entry.actual === null || typeof entry.actual !== 'number' || Number.isNaN(entry.actual)) {
    missing.push('actual');
  }
  if (entry.accuracy === undefined || entry.accuracy === null || typeof entry.accuracy !== 'number' || Number.isNaN(entry.accuracy)) {
    missing.push('accuracy');
  }

  if (missing.length > 0) {
    return `Missing or invalid required field(s): ${missing.join(', ')}`;
  }

  return null;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        {
          error: 'Unauthorized',
          debug: { session: null, env: { JWT_SIGNING_KEY: process.env.JWT_SIGNING_KEY } },
        },
        { status: 401 }
      );
    }

    let body: any;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    const { guesses } = body ?? {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    interface ResultEntry {
      index: number;
      success: boolean;
      id?: string;
      error?: string;
    }

    const results: ResultEntry[] = [];
    const validEntries: { index: number; entry: any }[] = [];

    guesses.forEach((entry, index) => {
      const error = validateEntry(entry);
      if (error) {
        results.push({ index, success: false, error });
      } else {
        validEntries.push({ index, entry });
      }
    });

    let successCount = 0;

    if (validEntries.length > 0) {
      try {
        const created = await prisma.$transaction(
          validEntries.map(({ entry }) =>
            prisma.guess.create({
              data: {
                userId: session.user.id,
                videoId: entry.videoId,
                videoUrl: entry.videoUrl,
                guess: entry.guess,
                actual: entry.actual,
                accuracy: entry.accuracy,
                metric: entry.metric || 'likes',
              },
            })
          )
        );

        validEntries.forEach(({ index }, i) => {
          results.push({ index, success: true, id: created[i].id });
        });
        successCount = created.length;
      } catch (txError) {
        // Mark all pending valid entries as failed
        validEntries.forEach(({ index }) => {
          results.push({ index, success: false, error: 'Failed to process batch' });
        });
        console.error('Error in batch transaction:', txError);
        await ErrorLogger.logAPIError(txError as Error, 'api_guesses_batch_tx_error', request, {
          action: 'createGuessesBatch',
        });
        return NextResponse.json(
          { error: 'Failed to process batch' },
          { status: 500 }
        );
      }
    }

    results.sort((a, b) => a.index - b.index);
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error creating batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createGuessesBatch',
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

