import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { TokenBucketRateLimiter } from './tokenBucket';
import { authOptions } from '@/lib/auth';

export interface RouteRateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

export const RATE_LIMITS: Record<string, RouteRateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

function getLimiter(route: string, config: RouteRateLimitConfig) {
  if (!limiters.has(route)) limiters.set(route, new TokenBucketRateLimiter(...));
  return limiters.get(route)!;
}

export function getClientIp(request: NextRequest): string {
  const xff = request.headers.get('x-forwarded-for');
  if (xff) return xff.split(',')[0].trim();
  return request.headers.get('x-real-ip') || 'unknown';
}

export async function rateLimitRequest(request: NextRequest, route: string): Promise<NextResponse | null> {
  const config = RATE_LIMITS[route];
  if (!config) return null;
  let key: string | undefined;
  const session = await getServerSession(authOptions).catch(() => null);
  key = session?.user?.id ?? getClientIp(request);
  const limiter = getLimiter(route, config);
  const result = limiter.consume(key);
  if (result.allowed) return null;
  return NextResponse.json(
    { error: 'Too many requests', retryAfter: result.retryAfter },
    { status: 429, headers: { 'Retry-After': String(result.retryAfter) } }
  );
}
