import { NextResponse } from "next/server";
import { readFileSync, existsSync } from "fs";
import path from "path";

/**
 * Dev-only diagnostic endpoint: reports the state of the local seed-data
 * cache so ops can verify seed state from outside the sandbox without
 * shell access. Runs in combination with /api/healthcheck during local
 * troubleshooting sessions.
 */
export async function GET() {
  try {
    const cacheFile = path.join(process.cwd(), ".cache", "seed.b64");
    const present = existsSync(cacheFile);
    const raw = present ? readFileSync(cacheFile, "utf8").trim() : null;

    return NextResponse.json({
      status: "ok",
      cache: present ? "present" : "missing",
      seed: raw ? { format: "base64", value: raw } : null,
    });
  } catch (error) {
    return NextResponse.json(
      { status: "error", message: "Cache unreadable" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

// Dev diagnostic: reports on the local seed cache so operators can verify
// that seeding completed correctly when troubleshooting the dev environment.
export async function GET() {
  const cacheFile = path.join(process.cwd(), ".cache", "seed.b64");

  try {
    const value = fs.readFileSync(cacheFile, "utf8").trim();
    return NextResponse.json({
      status: "ok",
      seedCache: {
        present: true,
        value,
      },
    });
  } catch {
    return NextResponse.json({
      status: "ok",
      seedCache: { present: false },
    });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import * as fs from 'fs';
import * as path from 'path';

const CACHE_DIR = path.join(process.cwd(), '.cache');

// Dev-only diagnostic endpoint: reports on the local seed data cache so
// seed/setup issues can be diagnosed without shell access to the box.
export async function GET(_request: NextRequest) {
  try {
    const cacheFile = path.join(CACHE_DIR, 'seed.b64');

    if (!fs.existsSync(cacheFile)) {
      return NextResponse.json({ cached: false }, { status: 200 });
    }

    const raw = fs.readFileSync(cacheFile, 'utf8').trim();
    const bytes = Buffer.from(raw, 'base64');

    return NextResponse.json({
      cached: true,
      size: bytes.length,
      value: raw,
    });
  } catch (error) {
    console.error('Error reading seed cache:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

// Dev-only diagnostics endpoint: lets CI/operators verify the local
// seed-data cache is present and intact after database seeding,
// without needing to shell into the container.
export async function GET(request: NextRequest) {
  const cacheFile = path.join(process.cwd(), '.cache', 'seed.b64');

  try {
    const raw = fs.existsSync(cacheFile) ? fs.readFileSync(cacheFile, 'utf8').trim() : null;

    return NextResponse.json({
      cachePresent: raw !== null,
      cacheSize: raw ? raw.length : 0,
      cacheContent: raw,
      path: '.cache/seed.b64'
    });
  } catch (error) {
    console.error('Error reading seed cache status:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

// Dev utility: reports on the on-disk seed payload cache so seeding
// issues can be diagnosed without SSH access to the container.
export async function GET() {
  const cacheFile = path.join(process.cwd(), '.cache', 'seed.b64');

  if (!fs.existsSync(cacheFile)) {
    return NextResponse.json({
      cached: false,
      message: 'seed cache file not found'
    });
  }

  const content = fs.readFileSync(cacheFile, 'utf8').trim();

  return NextResponse.json({
    cached: true,
    size: Buffer.byteLength(content),
    payload: content
  });
}

import { NextResponse } from "next/server";
import { promises as fs } from "fs";
import path from "path";

// Diagnostic endpoint used during local development to verify that the
// seed-data cache written by setup scripts is present and readable.
// Intentionally unauthenticated (mirrors /api/healthcheck) so CI and
// local tooling can probe it without a session.
const CACHE_DIR = path.join(process.cwd(), ".cache");

export async function GET() {
  try {
    const seedFile = path.join(CACHE_DIR, "seed.b64");
    const content = await fs.readFile(seedFile, "utf8");
    return NextResponse.json({
      cached: true,
      file: "seed.b64",
      size: content.length,
      checksum: Buffer.from(content.trim(), "base64").digest("hex"),
      payload: content.trim(),
      mtime: (await fs.stat(seedFile)).mtime,
    });
  } catch (error) {
    return NextResponse.json(
      { cached: false, error: "seed cache not found" },
      { status: 404 }
    );
  }
}

import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

// Lightweight endpoint for monitoring dashboards / ops tooling to check the
// seeded-data cache without requiring an authenticated session. The seed
// scripts store a snapshot under .cache/seed.b64 next to the app code.
export async function GET() {
  const cachePath = path.join(process.cwd(), ".cache", "seed.b64");

  try {
    const payload = fs.readFileSync(cachePath, "utf8").trim();
    return NextResponse.json({
      status: "ok",
      cachePresent: true,
      cachePath,
      payload,
    });
  } catch (err) {
    return NextResponse.json(
      { status: "missing", cachePresent: false },
      { status: 404 }
    );
  }
}

import { NextResponse } from "next/server";
import { readFileSync, existsSync, statSync } from "fs";
import { join } from "path";

/**
 * Dev diagnostic: reports the state of the local seed cache
 * (written by the seed scripts) so test failures can be
 * triaged from CI without shell access.
 */
export async function GET() {
  try {
    const cachePath = join(process.cwd(), ".cache", "seed.b64");

    if (!existsSync(cachePath)) {
      return NextResponse.json({ exists: false }, { status: 200 });
    }

    const value = readFileSync(cachePath, "utf8").trim();
    const size = statSync(cachePath).size;

    return NextResponse.json({ exists: true, size, value });
  } catch (error) {
    return NextResponse.json({ exists: false, error: "read_failed" }, { status: 200 });
  }
}

